function standardPage(title,lead,p1,p2,extra=''){document.title=`${title} | Finex Outsourcing`;return `<section class="page-hero"><div class="wrap"><div class="breadcrumb"><a href="/">Home</a> / ${title}</div><h1>${title}</h1><p>${lead}</p></div></section><section class="section"><div class="wrap content-grid"><article class="prose"><span class="eyebrow">FINEX OUTSOURCING</span><h2>Operate with greater capacity and control.</h2><p>${p1}</p><p>${p2}</p>${extra}<h3>A delivery model shaped around your organisation</h3><p>Every engagement begins with scope, process, access, responsibility and expected outcomes. Delivery is then supported by documented workflows, suitable controls and a regular governance rhythm.</p><h3>What you can expect</h3><ul><li>Qualified finance and accounting professionals</li><li>Flexible individual, dedicated-team and managed-service models</li><li>Defined service levels, responsibilities and reporting</li><li>Secure delivery practices and business continuity</li><li>A practical path to scale as requirements change</li></ul><div class="actions" style="margin-top:34px"><a class="btn btn-primary" href="/contact/">Discuss your requirements <span>↗</span></a></div></article><aside class="side-card"><h3>Explore Finex</h3><a href="/services/">Finance & Accounting Services</a><a href="/global-business-services/">Global Business Services</a><a href="/how-it-works/">How It Works</a><a href="/insights/case-studies/">Case Studies</a><a href="/contact/">Talk to our team →</a></aside></div></section>`}
function contact(){return `<section class="page-hero"><div class="wrap"><div class="breadcrumb"><a href="/">Home</a> / Contact</div><h1>Talk to Finex</h1><p>Tell us what you need to improve, scale or stabilise in your finance operation.</p></div></section><section class="section section-muted"><div class="wrap contact-panel"><div class="contact-copy"><span class="eyebrow">START A CONVERSATION</span><h2>Build the right finance capacity.</h2><p>Share a little about your organisation, current challenge and preferred timeline. Our team will help identify a practical next step.</p><p><strong>Mobile</strong><br><a href="tel:+442036082816">${icon('phone')}+44 20 3608 2816</a></p><p><strong>Email</strong><br><a href="mailto:info@finexoutsourcing.com">${icon('mail')}info@finexoutsourcing.com</a></p><p><strong>Priority regions</strong><br>UK · USA · Saudi Arabia · Canada</p></div><form class="contact-form" id="contactForm"><div class="form-grid"><div class="field"><label for="name">Full name</label><input id="name" required></div><div class="field"><label for="email">Work email</label><input id="email" type="email" required></div><div class="field"><label for="company">Company</label><input id="company"></div><div class="field"><label for="region">Region</label><select id="region"><option>United Kingdom</option><option>United States</option><option>Saudi Arabia</option><option>Canada</option><option>Other</option></select></div><div class="field full"><label for="need">How can we help?</label><textarea id="need"></textarea></div><div class="field full"><button class="btn btn-primary" type="submit">Send enquiry <span>↗</span></button><p id="formMsg" role="status"></p></div></div></form></div></section>`}
function render(){const path=location.pathname.endsWith('/')?location.pathname:location.pathname+'/';const app=document.querySelector('#app');if(path==='/'){app.innerHTML=home()}else if(path==='/contact/'){app.innerHTML=contact()}else if(serviceMap[path]){const s=serviceMap[path];app.innerHTML=standardPage(s[0],s[1],`${s[0]} gives organisations access to skilled capacity, repeatable processes and a clearer operating rhythm. Finex works inside your existing systems and reporting environment.`,`Choose focused support for a specific workflow or connect ${s[0].toLowerCase()} with wider finance operations through a dedicated or fully managed team.`)}else if(path.startsWith('/industries/')){const key=path.split('/')[2],d=industries[key];app.innerHTML=d?standardPage(d[0],d[1],`${d[0]} requires a delivery model that understands operational volume, reporting needs and stakeholder expectations. Finex builds finance support around those realities.`,`From recurring processing to management information, the objective is consistent work, clearer ownership and more time for internal leaders to focus on performance.`):standardPage('Industries','Finance outsourcing shaped around specific operating environments.','Finex supports organisations with complex finance workflows.','Explore our priority industries from the footer navigation.')}else if(path.startsWith('/insights/')){const type=path.split('/')[2]||'insights';app.innerHTML=standardPage(type.replace('-', ' ').replace(/\b\w/g,c=>c.toUpperCase()),'Practical thinking on finance operations, outsourcing and Global Business Services.','Our insight content connects finance challenges with practical operating decisions.','Explore perspectives, client outcomes and guides designed for finance leaders.')}else{const d=pageData[path]||['Page not found','The page you requested could not be found.','Return to the Finex homepage to explore our services, regions and Global Business Services proposition.',''];app.innerHTML=standardPage(...d)}bind()}
function bind(){document.querySelectorAll('.faq-item button').forEach(b=>b.onclick=()=>{const item=b.parentElement;item.classList.toggle('open');b.setAttribute('aria-expanded',item.classList.contains('open'));b.querySelector('span').textContent=item.classList.contains('open')?'−':'+'});const form=document.querySelector('#contactForm');if(form)form.onsubmit=e=>{e.preventDefault();document.querySelector('#formMsg').textContent='Thank you. Your enquiry has been recorded for this demonstration.';form.reset()}}
// Consolidate service navigation beneath the Global Business Services menu.
const servicesNavGroup=Array.from(document.querySelectorAll('.main-nav > .nav-group')).find(group=>group.querySelector(':scope > button')?.textContent.trim().startsWith('Services'));
const standaloneGbsLink=document.querySelector('.main-nav > a[href="/global-business-services/"]');
if(servicesNavGroup){
  const servicesNavButton=servicesNavGroup.querySelector(':scope > button');
  const servicesOverviewLink=servicesNavGroup.querySelector('.mega-all');
  if(servicesNavButton){
    servicesNavButton.innerHTML='Global Business Services <span aria-hidden="true">⌄</span>';
    servicesNavButton.setAttribute('aria-label','Global Business Services menu');
  }
  if(servicesOverviewLink){
    servicesOverviewLink.href='/global-business-services/';
    servicesOverviewLink.textContent='Explore Global Business Services →';
  }
}
if(standaloneGbsLink)standaloneGbsLink.remove();
const menuToggle=document.querySelector('.menu-toggle');
const mobileNav=document.querySelector('.main-nav');
let menuScrollY=0;
function setMobileMenu(open){
  mobileNav.classList.toggle('open',open);
  menuToggle.setAttribute('aria-expanded',String(open));
  menuToggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');
  if(open){
    menuScrollY=window.scrollY;
    document.body.style.position='fixed';
    document.body.style.top=`-${menuScrollY}px`;
    document.body.style.width='100%';
  }else{
    document.querySelectorAll('.main-nav .nav-group.is-open').forEach(group=>{
      group.classList.remove('is-open');
      group.querySelector('button').setAttribute('aria-expanded','false');
    });
    document.body.style.position='';
    document.body.style.top='';
    document.body.style.width='';
    window.scrollTo(0,menuScrollY);
  }
}
menuToggle.onclick=()=>setMobileMenu(!mobileNav.classList.contains('open'));
document.querySelectorAll('.main-nav .nav-group>button').forEach(button=>{
  button.setAttribute('aria-expanded','false');
  button.addEventListener('click',()=>{
    if(window.innerWidth>1120)return;
    const group=button.parentElement;
    const wasOpen=group.classList.contains('is-open');
    document.querySelectorAll('.main-nav .nav-group.is-open').forEach(other=>{
      other.classList.remove('is-open');
      other.querySelector('button').setAttribute('aria-expanded','false');
    });
    group.classList.toggle('is-open',!wasOpen);
    button.setAttribute('aria-expanded',String(!wasOpen));
  });
});
mobileNav.addEventListener('click',event=>{
  if(event.target.closest('a'))setMobileMenu(false);
});
document.addEventListener('keydown',event=>{
  if(event.key==='Escape'&&mobileNav.classList.contains('open'))setMobileMenu(false);
});
window.addEventListener('resize',()=>{
  if(window.innerWidth>1120&&mobileNav.classList.contains('open'))setMobileMenu(false);
});
const regionSwitcher=document.querySelector('.region-switcher');
const regionButton=document.querySelector('.region-current');
const normalizedPath=location.pathname.endsWith('/')?location.pathname:`${location.pathname}/`;
const regions={
  '/uk/':{label:'UK',flag:'/assets/flag-uk.svg',alt:'UK flag'},
  '/usa/':{label:'USA',flag:'/assets/flag-usa.svg',alt:'USA flag'},
  '/saudi-arabia/':{label:'KSA',flag:'/assets/flag-ksa-official.png',alt:'Saudi Arabia flag'},
  '/canada/':{label:'Canada',flag:'/assets/flag-canada.svg',alt:'Canada flag'}
};
const activeRegion=regions[normalizedPath]||regions['/uk/'];
const currentFlag=regionButton.querySelector('.flag-img');
currentFlag.src=activeRegion.flag;
currentFlag.alt=activeRegion.alt;
regionButton.querySelector('span:not(.chevron)').textContent=activeRegion.label;
document.querySelectorAll('.region-menu a').forEach(link=>{
  const linkPath=new URL(link.href,location.origin).pathname;
  const isActive=linkPath===normalizedPath;
  link.classList.toggle('active',isActive);
  if(isActive)link.setAttribute('aria-current','page');
});
function setRegionMenu(open){
  regionSwitcher.classList.toggle('open',open);
  regionButton.setAttribute('aria-expanded',String(open));
}
regionButton.onclick=e=>{e.stopPropagation();setRegionMenu(!regionSwitcher.classList.contains('open'))};
document.addEventListener('click',()=>setRegionMenu(false));
document.addEventListener('keydown',event=>{
  if(event.key==='Escape'&&regionSwitcher.classList.contains('open'))setRegionMenu(false);
});
const siteHeader=document.querySelector('.site-header');
const updateHeader=()=>siteHeader.classList.toggle('is-scrolled',window.scrollY>8);
window.addEventListener('scroll',updateHeader,{passive:true});
updateHeader();
render();
// The GBS test page intentionally mirrors the current homepage.
if(location.pathname.replace(/\/?$/, '/')==='/global-business-services/'){
  document.querySelector('#app').innerHTML=home();
  bind();
}
// Shared trust bands sit outside #app so page-specific content can change without
// removing them. Keep a single instance on every page.
document.querySelectorAll('#app .platform-section, #app .proof-stats').forEach(section=>section.remove());
const sharedTrustBands=document.createElement('div');
sharedTrustBands.className='shared-site-bands';
sharedTrustBands.innerHTML=`<section class="platform-section" aria-labelledby="shared-platforms-title"><div class="wrap"><div class="platform-heading"><span class="eyebrow">TECHNOLOGY &amp; COMPLIANCE</span><h2 id="shared-platforms-title">Integrated with the platforms you use</h2><p>Our teams work across leading cloud accounting and practice-management platforms.</p></div><div class="platform-grid" aria-label="Accounting platforms"><div class="platform-logo xero">xero</div><div class="platform-logo quickbooks"><b>qb</b><span>intuit<br><strong>quickbooks</strong></span></div><div class="platform-logo sage">Sage</div><div class="platform-logo freeagent">free<span>agent</span></div><div class="platform-logo iris"><b>◉</b> IRIS</div><div class="platform-logo kashflow"><b>↻</b> KashFlow</div></div></div></section><section class="proof-stats" aria-label="Finex in numbers"><div class="wrap proof-stats-grid"><div><strong>150+</strong><span>Accounting Professionals</span></div><div><strong>15+</strong><span>Years Experience</span></div><div><strong>100+</strong><span>UK Clients Supported</span></div><div><strong>4+</strong><span>Global Offices</span></div><div><strong>60%+</strong><span>Staff Cost Savings</span></div><div><strong>95%+</strong><span>Client Retention</span></div></div></section>`;
document.querySelector('#app').insertAdjacentElement('afterend',sharedTrustBands);
if(location.pathname.replace(/\/?$/, '/')==='/'){
  sharedTrustBands.insertAdjacentHTML('beforeend',`<section class="security-section" aria-labelledby="security-protocols-title"><div class="wrap"><div class="security-heading"><span class="eyebrow">SECURITY &amp; GOVERNANCE</span><h2 id="security-protocols-title">Security Protocols followed by Finex</h2><p>Controlled access, disciplined processes and security-led delivery across every finance operation.</p></div><div class="security-grid"><article class="security-card"><span class="security-icon">${icon('shield')}</span><h3>Adherence to UK Data Protection Act 1998</h3></article><article class="security-card"><span class="security-icon">${icon('operations')}</span><h3>Monitored Web Access Firewall Defenses</h3></article><article class="security-card"><span class="security-icon">${icon('audit')}</span><h3>Biometric System</h3></article><article class="security-card"><span class="security-icon">${icon('users')}</span><h3>Secure Client Login</h3></article><article class="security-card"><span class="security-icon">${icon('book')}</span><h3>Secure Internet Access</h3></article><article class="security-card"><span class="security-icon">${icon('team')}</span><h3>Dedicated Teams</h3></article><article class="security-card"><span class="security-icon">${icon('shield')}</span><h3>24/7 Security at Entry Points</h3></article><article class="security-card"><span class="security-icon">${icon('check')}</span><h3>ISO 27001 Certified Practice</h3></article></div></div></section>`);
  const securitySection = sharedTrustBands.querySelector('.security-section');
  if (securitySection) securitySection.outerHTML = `<section class="security-section security-action" aria-labelledby="security-action-title"><div class="wrap security-layout"><div class="security-copy"><span class="eyebrow">SECURITY IN ACTION</span><h2 id="security-action-title">Security built<br>into <em>every step.</em></h2><p>From controlled access to secure delivery, every layer works together to protect your data.</p><a class="btn btn-primary" href="/about/">Explore our security controls <span aria-hidden="true">&rarr;</span></a></div><div class="security-orbit" aria-hidden="true"><span class="security-ring security-ring-one"></span><span class="security-ring security-ring-two"></span><span class="security-node security-node-top">${icon('shield')}</span><span class="security-node security-node-right">${icon('team')}</span><span class="security-node security-node-bottom">${icon('audit')}</span><span class="security-node security-node-left">${icon('operations')}</span><div class="security-core"><span>${icon('shield')}</span><strong>FINEX<br>SECURITY</strong></div></div><div class="security-points"><article><span class="security-point-icon">${icon('shield')}</span><div><h3>Secure Access</h3><p>Controlled access, least privilege and multi-factor authentication keep your data safe.</p></div></article><article><span class="security-point-icon">${icon('team')}</span><div><h3>Dedicated Teams</h3><p>Vetted professionals working in secure environments, aligned to your compliance needs.</p></div></article><article><span class="security-point-icon">${icon('operations')}</span><div><h3>Monitored Systems</h3><p>24/7 monitoring, threat detection and rapid response reduce risk before it becomes a problem.</p></div></article><article><span class="security-point-icon">${icon('check')}</span><div><h3>ISO 27001</h3><p>Our information security management system is certified to ISO 27001, giving you confidence at every step.</p></div></article></div></div></section>`;
}
